using System;
using System.IO;

class Program
{
    static void Main()
    {
        string filePath = "todo.txt";

        // Check if file exists before reading
        if (!File.Exists(filePath))
        {
            Console.WriteLine("todo.txt not found. Creating sample file...");
            string[] sampleLines = { "Buy groceries", "Finish homework", "Walk the dog" };
            File.WriteAllLines(filePath, sampleLines);
        }

        // Read all lines into an array
        string[] lines = File.ReadAllLines(filePath);

        Console.WriteLine($"Found {lines.Length} tasks:");

        int taskNumber = 1;
        foreach (string line in lines)
        {
            // Trim whitespace and skip empty lines
            string trimmed = line.Trim();
            if (!string.IsNullOrEmpty(trimmed))
            {
                Console.WriteLine($"{taskNumber}. {trimmed}");
                taskNumber++;
            }
        }
    }
}

using System;
using System.IO;

class Program
{
    static void Main()
    {
        string filePath = "journal.txt";

        // Write initial content (overwrites any existing file)
        File.WriteAllText(filePath, "Day 1: Started learning C#!\n");
        Console.WriteLine("Created journal.txt with initial entry.");

        // Append a new line without removing existing content
        File.AppendAllText(filePath, "Day 2: Learned about File I/O.\n");
        Console.WriteLine("Appended Day 2 entry.");

        // Write multiple lines at once (overwrites file)
        string[] allEntries =
        {
            "Day 1: Started learning C#!",
            "Day 2: Learned about File I/O.",
            "Day 3: Mastered streams!"
        };
        File.WriteAllLines(filePath, allEntries);
        Console.WriteLine("Rewrote journal.txt with all three entries.");

        // Read and display final file
        Console.WriteLine("\nFinal journal contents:");
        Console.WriteLine(File.ReadAllText(filePath));
    }
}

using System;
using System.IO;

class Program
{
    static void Main()
    {
        string inputPath = "large-data.csv";
        string outputPath = "summary.txt";

        // Create a sample large file for demonstration
        if (!File.Exists(inputPath))
        {
            using StreamWriter writer = new StreamWriter(inputPath);
            for (int i = 1; i <= 10; i++)
            {
                writer.WriteLine($"Row {i},Value {i * 10}");
            }
        }

        // Use StreamReader to read line by line
        using StreamReader reader = new StreamReader(inputPath);
        using StreamWriter writer = new StreamWriter(outputPath);

        string line;
        int lineCount = 0;

        // ReadLine returns null when end of file is reached
        while ((line = reader.ReadLine()) != null)
        {
            lineCount++;
            Console.WriteLine($"Line {lineCount}: {line}");
            writer.WriteLine($"Processed: {line}");
        }

        Console.WriteLine($"\nProcessed {lineCount} lines.");
    }
}

using System;
using System.IO;

class Program
{
    static void Main()
    {
        string filePath = "inventory.csv";

        // StreamWriter uses a buffer to batch writes efficiently
        // The 'using' statement ensures Dispose is called automatically
        using StreamWriter writer = new StreamWriter(filePath);

        // Write a header row
        writer.WriteLine("Product,Price,Stock");

        // Write data rows
        string[] products =
        {
            { "Laptop", "999.99", "15" },
            { "Mouse", "25.50", "100" },
            { "Keyboard", "79.99", "45" }
        };

        for (int row = 0; row < products.GetLength(0); row++)
        {
            writer.WriteLine($"{products[row, 0]},{products[row, 1]},{products[row, 2]}");
        }

        Console.WriteLine("Inventory saved to inventory.csv");

        // StreamWriter auto-flushes on Dispose when the 'using' block ends
    }
}

using System;
using System.IO;

class Program
{
    static void Main()
    {
        string baseFolder = "MyAppData";
        string subFolder = "Logs";

        // Build the full path safely (cross-platform)
        string fullPath = Path.Combine(baseFolder, subFolder, "app.log");
        Console.WriteLine($"Full path: {fullPath}");

        // Get folder name and file name from a path
        string directory = Path.GetDirectoryName(fullPath);
        string fileName = Path.GetFileName(fullPath);
        string extension = Path.GetExtension(fullPath);
        Console.WriteLine($"Directory: {directory}");
        Console.WriteLine($"File: {fileName}");
        Console.WriteLine($"Extension: {extension}");

        // Create directory if it doesn't exist
        if (!Directory.Exists(baseFolder))
        {
            Directory.CreateDirectory(Path.Combine(baseFolder, subFolder));
            Console.WriteLine($"Created directory: {baseFolder}/{subFolder}");
        }

        // List all .txt files in a directory
        if (Directory.Exists(baseFolder))
        {
            string[] txtFiles = Directory.GetFiles(baseFolder, "*.txt", SearchOption.AllDirectories);
            Console.WriteLine($"\n.txt files found: {txtFiles.Length}");
            foreach (string file in txtFiles)
            {
                Console.WriteLine(file);
            }
        }
    }
}

using System;
using System.IO;
using System.Threading.Tasks;

class Program
{
    // Mark the method as async so we can await inside it
    static async Task Main()
    {
        string filePath = "async-demo.txt";
        string largeContent = new string('*', 1_000_000); // 1 MB of asterisks

        // Write asynchronously — the thread is free to do other work
        await File.WriteAllTextAsync(filePath, largeContent);
        Console.WriteLine("File written asynchronously.");

        // Read asynchronously
        string readBack = await File.ReadAllTextAsync(filePath);
        Console.WriteLine($"Read back {readBack.Length:N0} characters asynchronously.");

        // StreamReader async example
        using StreamReader reader = new StreamReader(filePath);
        char[] buffer = new char[4096];
        int bytesRead = await reader.ReadAsync(buffer, 0, buffer.Length);
        Console.WriteLine($"First chunk: {new string(buffer, 0, bytesRead)}");
    }
}
